    ('2d90a75b-f1bd-537e-af46-abe9fb127cf7'::uuid, 'b389555c-dcae-5592-b4ae-0d3f779916a3'::uuid, '« Look at those clouds — it’s going to rain » exprime…', 'mcq', '["Une prédiction fondée sur un indice visible","Une décision prise à l’instant","Un horaire officiel","Une promesse"]'::jsonb, 0, '*Be going to* s’appuie sur le présent visible.', 1),
    ('51e12807-a4fd-5a11-9cc1-1727463e2adb'::uuid, 'b389555c-dcae-5592-b4ae-0d3f779916a3'::uuid, '*I’ll call you when I ___ home.*', 'mcq', '["get","will get","would get","got"]'::jsonb, 0, 'Deux futurs français, un seul futur anglais : la subordonnée reste au présent.', 2),
    ('20f97134-6ddd-5df9-b6b5-785a09b72866'::uuid, 'b389555c-dcae-5592-b4ae-0d3f779916a3'::uuid, '« The train leaves at 6 » convient pour un horaire officiel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le présent simple s’emploie pour les programmes fixés institutionnellement.', 3),
    ('32ae53a1-0091-5f38-b9d3-c32a85ce0199'::uuid, 'b389555c-dcae-5592-b4ae-0d3f779916a3'::uuid, 'Dans une hypothèse de type 2, la subordonnée est au…', 'mcq', '["Prétérit","Présent","Present perfect","Conditionnel"]'::jsonb, 0, '*If I had money, I would travel.*', 4),
