    ('98a845c0-32da-5b37-b40d-4e519a6c5086'::uuid, 'b389555c-dcae-5592-b4ae-0d3f779916a3'::uuid, '« If I were you » est la forme soignée de l’irréel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Were* s’emploie à toutes les personnes dans cette structure.', 7),
