    ('e75697ff-6480-54ec-99d0-ec6d50e73849'::uuid, 'ac8ebdd9-ea7e-5354-b307-a8752ddc570f'::uuid, 'Quel est l’ordre correct ?', 'mcq', '["Where does she live?","Where she lives?","Where does she lives?","Where lives she?"]'::jsonb, 0, 'Auxiliaire + sujet + base verbale.', 1),
    ('1854d087-a323-5184-bcb9-d57e37d4824c'::uuid, 'ac8ebdd9-ea7e-5354-b307-a8752ddc570f'::uuid, '« Who did break the window? » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand *who* est sujet, pas d’auxiliaire : *Who broke the window?*', 2),
