    ('90b12913-38fc-5578-acfb-c1c6a79e620a'::uuid, 'ac8ebdd9-ea7e-5354-b307-a8752ddc570f'::uuid, '« What is she like? » demande…', 'mcq', '["Comment elle est (caractère, description)","Ce qu’elle aime","Comment elle va","Ce qu’elle fait"]'::jsonb, 0, '*How is she?* porterait sur sa santé ou son humeur.', 4),
