    ('4aaf5574-8e75-58e1-845b-1a16d0618c03'::uuid, 'ac8ebdd9-ea7e-5354-b307-a8752ddc570f'::uuid, 'Dans une question, le verbe lexical reste à la base verbale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Does she live*, jamais *does she lives*.', 6),
    ('1b4652a9-ef01-53f4-8c11-3a961812b638'::uuid, 'ac8ebdd9-ea7e-5354-b307-a8752ddc570f'::uuid, '« Which » s’emploie plutôt quand…', 'mcq', '["Le choix est limité à un ensemble connu","On ignore tout de l’ensemble","On interroge sur une personne","On interroge sur un lieu"]'::jsonb, 0, '*Which of these two do you prefer?*', 7),
