    ('6d454d93-c959-598a-9369-0fece4a89206'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, 'Comment traduit-on « Quelle belle journée ! » ?', 'mcq', '["What a beautiful day!","How a beautiful day!","What beautiful day!","How beautiful day!"]'::jsonb, 0, '*What* + nom, avec l’article au singulier dénombrable.', 1),
    ('5126b518-cd10-5a94-8e91-700ddd4eb466'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, '« What terrible weather! » est correct sans article.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Weather* est indénombrable : pas de *a*.', 2),
    ('c95231ec-371c-51cd-b618-752444617210'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, '« How » introduit…', 'mcq', '["Un adjectif ou un adverbe","Un nom","Un verbe conjugué","Un sujet"]'::jsonb, 0, '*How strange!*, *How beautifully she sings!*', 3),
    ('8a7e272e-14ff-56e3-bdd5-284e23b9ab45'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, 'Dans une exclamative, on inverse sujet et verbe comme dans une question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’ordre reste normal : *What a mess this is!*', 4),
    ('3c2dc757-534d-5894-9450-7cd7f70502dd'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, 'Quelle forme est correcte ?', 'mcq', '["It’s such a mess","It’s so a mess","It’s such mess","It’s so mess"]'::jsonb, 0, '*Such* + groupe nominal, *so* + adjectif.', 5),
    ('adbf264b-ae5e-5eff-a584-dbe4557033f5'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, '« How kind of you to come! » est une exclamation correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*How* + adjectif, complété par un infinitif.', 6),
    ('584a008a-676e-5f15-814f-b5bf3cf9ee88'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, '« What lovely flowers! » ne prend pas d’article parce que…', 'mcq', '["Le nom est au pluriel","Le nom est abstrait","L’adjectif commence par une consonne","C’est une exception"]'::jsonb, 0, '*A / an* n’existe qu’au singulier.', 7),
    ('a3b24f5d-f012-51b1-88ee-eeb96ff5974c'::uuid, '74ba96e7-6094-546a-8c94-f38dc4afc74c'::uuid, '« It’s so cold! » exprime une exclamation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*So* + adjectif est la tournure courante à l’oral.', 8),
