    ('14bf8236-6924-543e-afe3-8eaee0437ae7'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, '« More taller » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule marque de comparatif à la fois.', 2),
    ('0a40bbe8-0696-5725-abdb-52b716febd87'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, 'Quel est le superlatif de « good » ?', 'mcq', '["the best","the goodest","the better","the most good"]'::jsonb, 0, 'Irrégulier : *good – better – the best*.', 3),
    ('dfdeec92-8cc6-5a14-a94c-b7b99501f2f9'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, '« Big » fait son comparatif en…', 'mcq', '["bigger","biger","more big","biggest"]'::jsonb, 0, 'La consonne finale double après une voyelle courte.', 4),
    ('2acfeccb-3eb8-59ca-bfd7-d989b0bf54ff'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, '« As tall as » exprime l’égalité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et *not as tall as* l’infériorité.', 5),
    ('6a88f1fa-71dd-53ba-8a79-7c2063a8e23e'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, 'Comment traduit-on « Plus je lis, plus je comprends » ?', 'mcq', '["The more I read, the more I understand","More I read, more I understand","The most I read, the most I understand","More and more I read"]'::jsonb, 0, 'Structure *the more … the more*.', 6),
    ('8aa178d9-2d20-5c0b-8278-58ea05323a02'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, 'Le superlatif s’emploie sans article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il prend toujours *the* : *the tallest building*.', 7),
    ('7f1a8239-aeae-593a-bb18-3f943a77eab7'::uuid, '182f7a0e-029b-56a5-ba02-936ee73fe756'::uuid, 'Quel est le comparatif de « bad » ?', 'mcq', '["worse","badder","more bad","worst"]'::jsonb, 0, '*Bad – worse – the worst*.', 8),
    ('f467979e-efa7-577f-9849-79e6dde00e41'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, 'Quel relatif exprime la possession ?', 'mcq', '["whose","which","who","whom"]'::jsonb, 0, '*The student whose bag was stolen.*', 1),
    ('38e63cd9-87a4-56bb-9066-8c0f293e1e6a'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, 'Une relative appositive peut être introduite par « that ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Entre virgules, on emploie *who* ou *which*, jamais *that*.', 2),
    ('ee6446e3-4b5f-5f12-a8ac-cf4e550162b4'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, '« The book I read yesterday » est correct sans relatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le relatif complément peut s’effacer.', 3),
    ('20f3faea-7a86-5b9b-8698-5d55cbfdd399'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, 'Dans « The man who called is my uncle », la relative…', 'mcq', '["Identifie de quel homme on parle","Ajoute une information accessoire","Exprime une cause","Exprime une condition"]'::jsonb, 0, 'Relative déterminative : pas de virgule.', 4),
    ('a516233a-2687-5820-a0f6-175342da8ac9'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, 'Quel verbe exige un complément de personne ?', 'mcq', '["tell","say","think","hope"]'::jsonb, 0, '*Tell me*, mais *say to me*.', 5),
    ('491ef03c-7cac-56ca-97c9-9cfd5b7e9a69'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, '« Although » introduit…', 'mcq', '["Une concession","Une cause","Un but","Une condition"]'::jsonb, 0, '*Although it was raining, we went out.*', 6),
    ('4a0479e5-5380-5074-9690-deccc752912f'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, 'Après « until », on emploie le futur avec « will ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme après *when* et *if* : présent obligatoire.', 7),
    ('a4344945-4fa4-5767-b233-435299e7cdb0'::uuid, 'de989074-af34-5548-a87a-6fb8cd011708'::uuid, '« So that » introduit…', 'mcq', '["Un but","Une conséquence datée","Une comparaison","Une opposition"]'::jsonb, 0, '*He left early so that he could catch the train.*', 8),
    ('8b72296d-0b6c-5d89-a078-5ad75ec30d73'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, 'Lequel introduit un point de départ ?', 'mcq', '["since","for","ago","during"]'::jsonb, 0, '*Since 2019*, *since Monday*.', 1),
    ('683691f0-66cc-55ad-a8ea-c2811f77a6c2'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, '« I have lived here since six years » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une durée appelle *for* : *for six years*.', 2),
    ('70651427-983c-52e3-95db-bb82f9a5c816'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, '« Ago » s’emploie avec…', 'mcq', '["Le prétérit","Le present perfect","Le présent","Le past perfect"]'::jsonb, 0, '*I met her three days ago.*', 3),
    ('8f1d00be-0537-5a98-b52b-2a092c820c76'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, 'Quelle forme est correcte ?', 'mcq', '["During the meeting","During we were talking","While the meeting","While of the meeting"]'::jsonb, 0, '*During* + nom, *while* + proposition.', 4),
    ('b65a693f-0e79-5b6a-887a-da26b469dff6'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, '« By Friday » signifie « jusqu’à vendredi ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela signifie « d’ici vendredi, au plus tard » ; « jusqu’à » se dit *until*.', 5),
    ('ef91252d-c6c0-5b4d-a117-bd70bc64c1c8'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, '« In two weeks » signifie…', 'mcq', '["Dans deux semaines","Il y a deux semaines","Pendant deux semaines","Depuis deux semaines"]'::jsonb, 0, 'Pour « pendant », il faudrait *for*.', 6),
    ('375fd4ca-1f54-5880-84d4-ead18609e00b'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, '« Since » va le plus souvent avec le present perfect.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il relie un point du passé au présent.', 7),
    ('e89711ad-e78b-5536-a833-092d8b03b317'::uuid, 'e525495c-a01c-5d42-b245-41d10ad0ddb7'::uuid, 'Comment traduit-on « pendant la réunion » ?', 'mcq', '["During the meeting","While the meeting","For the meeting","Since the meeting"]'::jsonb, 0, 'Un nom appelle *during*.', 8),
    ('9d9928e3-d896-59ae-9e56-90f10b1f9d13'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, 'Quelle forme est correcte ?', 'mcq', '["Because of the rain","Because of it was raining","Because the rain","Due to it rained"]'::jsonb, 0, '*Because of* est suivi d’un groupe nominal.', 1),
    ('dcf7a709-ec83-5270-88c1-da2e4732eaf0'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, '« I came for help you » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le but devant un verbe se dit *to help*, jamais *for to*.', 2),
    ('525e842a-b171-576d-bb62-0bdf706e60dd'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, '« So that » s’emploie surtout quand…', 'mcq', '["Le sujet du but est différent","Le sujet est le même","La cause est connue","On exprime une conséquence datée"]'::jsonb, 0, '*He spoke slowly so that everyone could understand.*', 3),
    ('74785236-c352-5e3b-a12a-4d5e466b5c3a'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, '« As it was late, we left » exprime une cause.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*As* et *since* introduisent une cause souvent déjà connue.', 4),
    ('3e54dbd9-e49a-5e5e-93c3-c294c2aa20bc'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, 'Comment dit-on « afin de ne pas être en retard » ?', 'mcq', '["So as not to be late","So as to not be late","For not being late","To not be late"]'::jsonb, 0, 'La négation se place devant *to* dans cette structure.', 5),
    ('dcf49bf5-2190-50eb-809f-5920b8ec9ba1'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, '« Thanks to » introduit une cause négative.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’emploie pour une cause positive ; sinon *because of*, *owing to*.', 6),
