    ('ff131b80-5f79-53eb-ac90-16fc5c2b332f'::uuid, 'e2a44cf9-3991-5cdf-8542-8d8922289cd5'::uuid, '« In order to » est plus formel que « to » seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Même sens, registre plus soutenu.', 8),
    ('5bc9e08a-68a7-5ba0-8f5e-c4f869255988'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« Unless you hurry » signifie…', 'mcq', '["Si tu ne te dépêches pas","Si tu te dépêches","Bien que tu te dépêches","Pendant que tu te dépêches"]'::jsonb, 0, '*Unless* contient déjà la négation.', 1),
    ('0f06f369-a39d-5b5d-8887-aebdfffe75fd'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« Despite he was tired » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Despite* est une préposition : *despite being tired* ou *although he was tired*.', 2),
    ('3f058eb0-07f9-5754-963d-0d136e0cbc72'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, 'Quelle structure suit « in spite of » ?', 'mcq', '["Un nom ou un -ING","Une proposition complète","Un infinitif","Un modal"]'::jsonb, 0, 'Comme *despite*.', 3),
    ('9aab939e-4de3-58d7-b74c-b9c9f567380d'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« Whereas » exprime…', 'mcq', '["Une opposition entre deux faits","Une condition","Une cause","Un but"]'::jsonb, 0, '*He likes tea, whereas she prefers coffee.*', 4),
    ('9cf8a277-5d76-5328-a5c2-83e147d82d69'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« If I had money, I would travel » relève de l’irréel du présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Type 2 : prétérit dans la subordonnée, *would* dans la principale.', 5),
    ('d452a200-8d2a-5b0f-a7fd-faa40f70b1c4'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« Although » introduit une proposition complète.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec sujet et verbe conjugué.', 6),
    ('aac3c54a-8fc5-5656-aeaf-de74bda42826'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« In case it rains » signifie…', 'mcq', '["Au cas où il pleuvrait","S’il pleut, alors","Bien qu’il pleuve","Puisqu’il pleut"]'::jsonb, 0, 'La précaution prise par avance.', 7),
    ('1598b281-2d46-5f19-8e07-cfb54fc2ccd8'::uuid, 'ac4cfe40-4739-5a23-9bf1-068eafc9ec2e'::uuid, '« However » s’emploie pour…', 'mcq', '["Marquer une opposition entre deux phrases","Introduire une condition","Exprimer un but","Introduire une cause"]'::jsonb, 0, 'Souvent en tête de phrase, suivi d’une virgule.', 8),
    ('4c0c1909-addc-55d1-870a-dc07b780caa6'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, '« I used to smoke » signifie…', 'mcq', '["Je fumais autrefois, mais plus maintenant","J’ai l’habitude de fumer","Je me suis habitué à fumer","Je vais fumer"]'::jsonb, 0, '*Used to* implique toujours une rupture avec le présent.', 1),
    ('e27cce81-d75f-5e62-ad92-4c2a47ba55a0'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, '« I’m used to getting up early » signifie…', 'mcq', '["J’ai l’habitude de me lever tôt","Je me levais tôt autrefois","Je vais me lever tôt","Je déteste me lever tôt"]'::jsonb, 0, 'Ici *to* est une préposition, d’où le -ING.', 2),
    ('8fc7de0e-ace4-5b2a-8036-0d249506170e'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, '« I would live in York » est correct pour une habitude passée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Would* ne s’emploie pas pour un état : *I used to live in York*.', 3),
    ('06267b0d-b7c4-55ac-823d-44988ca522ba'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, 'La négation de « used to » est…', 'mcq', '["I didn’t use to","I didn’t used to","I usen’t to","I not used to"]'::jsonb, 0, '*Did* porte le passé, donc *use* sans -d.', 4),
    ('52f9623b-47cc-59bb-a8b1-8eae686a8537'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, '« Every summer, we would go to the seaside » évoque une habitude passée répétée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Valeur fréquentative de *would* dans un récit.', 5),
    ('97ab25cf-ea7d-5230-a783-955e966a6244'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, '« Get used to » signifie…', 'mcq', '["S’habituer progressivement","Avoir toujours été habitué","Perdre une habitude","Refuser une habitude"]'::jsonb, 0, '*You’ll get used to it.*', 6),
    ('8c871ad7-0def-587c-9965-ca07335a0a6b'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, 'L’habitude au présent se rend par…', 'mcq', '["Le présent simple + adverbe de fréquence","used to + base verbale","would + base verbale","be + -ing"]'::jsonb, 0, '*I usually walk to school.*', 7),
    ('fa5b03eb-6cf8-5c5b-9af7-79befa9d90b2'::uuid, '1a8fa390-1d14-568e-b396-bdee46c99148'::uuid, 'Après « be used to », on emploie la base verbale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie la forme en -ING : *used to getting up*.', 8),
    ('f6bd5bf1-3545-540a-aea0-5f8b52d72c24'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, 'Quelle construction suit « make » à l’actif ?', 'mcq', '["make + complément + base verbale","make + complément + to + base verbale","make + -ing","make + participe passé"]'::jsonb, 0, '*She made me wait.*', 1),
    ('4a993c00-1df5-5a57-950c-8963556b7d49'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, '« I was made to wait » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Au passif, *make* retrouve le *to*.', 2),
    ('b2443cf1-dbf2-5d7a-8f86-6843cdaccb64'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, 'Lequel se construit avec « to » ?', 'mcq', '["get","make","have","let"]'::jsonb, 0, '*I got him to help me.*', 3),
    ('d425a1a9-bff9-5cdc-8b6d-900acb45028f'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, '« I had my hair cut » signifie…', 'mcq', '["Je me suis fait couper les cheveux","J’ai coupé mes cheveux moi-même","J’avais les cheveux coupés courts","Je voulais couper mes cheveux"]'::jsonb, 0, 'La structure *have something done* désigne l’action d’un tiers.', 4),
    ('532f8959-5fd8-5fca-8f9e-05998c881e6f'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, '« Let » exprime la permission.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Let me explain*, *they let him go*.', 5),
    ('7547e325-b185-5e89-9d07-b20cef332ec9'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, 'Au passif, on remplace « let » par…', 'mcq', '["allow","make","have","get"]'::jsonb, 0, '*He was allowed to go.*', 6),
    ('9a39ff68-9162-5cf0-b230-59967ac37632'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, '« She got her car repaired » signifie qu’elle a réparé la voiture elle-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’a fait réparer : structure *get something done*.', 7),
